import{_ as a,o as i,c as t,a3 as e}from"./chunks/framework.WFmvnizL.js";const c=JSON.parse('{"title":"测试、贡献与发布检查","description":"哪吒监控贡献与测试指南：Dashboard/Agent 的 Go、race、vet，用户和管理前端验证，文档构建、跨仓库联调与高质量 PR 交付。","frontmatter":{"description":"哪吒监控贡献与测试指南：Dashboard/Agent 的 Go、race、vet，用户和管理前端验证，文档构建、跨仓库联调与高质量 PR 交付。","outline":"deep"},"headers":[],"relativePath":"developer/testing.md","filePath":"developer/testing.md","lastUpdated":1792850916000}'),n={name:"developer/testing.md"};function h(l,s,p,d,k,r){return i(),t("div",null,[...s[0]||(s[0]=[e(`<h1 id="测试、贡献与发布检查" tabindex="-1">测试、贡献与发布检查 <a class="header-anchor" href="#测试、贡献与发布检查" aria-label="Permalink to &quot;测试、贡献与发布检查&quot;">​</a></h1><p>测试应匹配改动层次。纯文档修改不必重建整个 Agent；协议/生命周期修改也不能只靠网页能打开判断成功。以下命令是开发者可运行的检查，不表示每次改动都已代为运行全部项目测试。</p><h2 id="go-后端与-agent" tabindex="-1">Go 后端与 Agent <a class="header-anchor" href="#go-后端与-agent" aria-label="Permalink to &quot;Go 后端与 Agent&quot;">​</a></h2><p>先按<a href="/developer/getting-started.html">快速开始</a>为 Dashboard 生成 Swagger 并准备非空前端输入，再在各仓库根目录运行：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">go</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -mod=readonly</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -count=1</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./...</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">go</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vet</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./...</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">go</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -mod=readonly</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -race</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -shuffle=on</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -count=1</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./...</span></span></code></pre></div><p><code>-race</code> 需受支持的平台和 C 编译器。普通测试检查功能，race 检查并发访问，不互相替代。新增回归测试应复现原问题而非只照抄实现。</p><p>两个仓库的 <code>.github/workflows/test.yml</code> 包含普通、race/质量和跨仓库压力验证；<code>agentcompat</code> 使用固定源码组合与专门 build tags。修改上报、重连、任务恰好一次执行或退出清理时，复用该工作流的固定配对和场景，不擅自省略测试步骤或改成任意 latest。</p><h2 id="用户主题" tabindex="-1">用户主题 <a class="header-anchor" href="#用户主题" aria-label="Permalink to &quot;用户主题&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --frozen-lockfile</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> verify</span></span></code></pre></div><p>当前脚本组合代码检查、覆盖率、类型检查和生产构建。覆盖率达标不等于图表视觉正确；mock 和测试替身也不证明真实后端权限、断线或资源发布正常。前端主分支与 Dashboard manifest 打包版本分别检查。</p><h2 id="管理前端" tabindex="-1">管理前端 <a class="header-anchor" href="#管理前端" aria-label="Permalink to &quot;管理前端&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ci</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lint</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span></code></pre></div><p>需要真实登录/表单/路由联调时运行仓库 Playwright：先按 README 启动隔离后端，再准备浏览器并执行：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> e2e:install</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> e2e</span></span></code></pre></div><p>E2E 会操作后台状态，不指向生产。失败时保留报告、后端日志与具体 URL，但移除凭据。</p><h2 id="文档" tabindex="-1">文档 <a class="header-anchor" href="#文档" aria-label="Permalink to &quot;文档&quot;">​</a></h2><p>在文档仓库根目录运行：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ci</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> diff</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --check</span></span></code></pre></div><p><code>npm test</code> 包含 VitePress 构建、SEO/双语页面与内部链接检查，以及 MCP 组件测试。新增页面同时更新中英文导航、相关页面链接和适用的 <code>llms.txt</code> 入口；元描述准确说明该页解决的问题。</p><h2 id="浏览器验收矩阵" tabindex="-1">浏览器验收矩阵 <a class="header-anchor" href="#浏览器验收矩阵" aria-label="Permalink to &quot;浏览器验收矩阵&quot;">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>最低覆盖</th></tr></thead><tbody><tr><td>身份</td><td>游客、成员、管理员、过期会话与强制登录</td></tr><tr><td>路由</td><td>直接打开/刷新、前端跳转、HTTP 状态和资源 base</td></tr><tr><td>数据</td><td>无节点、离线、缺失字段、TSDB 开/关、空历史</td></tr><tr><td>故障</td><td>网络断开/恢复、超时、乱序请求、失败可重试</td></tr><tr><td>布局</td><td>桌面、窄屏、长文本、深浅色、键盘焦点</td></tr></tbody></table><p>记录浏览器与视口；模拟窄屏不能写成真实手机验收。未运行的检查明确标为未验证，不用单元测试结果替代视觉结论。</p><h2 id="提交与回退" tabindex="-1">提交与回退 <a class="header-anchor" href="#提交与回退" aria-label="Permalink to &quot;提交与回退&quot;">​</a></h2><p>使用独立分支，写清问题、修改、兼容范围和已运行检查。保持锁文件与生成产物符合所在仓库规则；不要提交开发数据库、日志中的 Token 或测试用户密钥。</p><p>主题保留上一版静态产物；存储和配置变更提供<a href="/guide/q5.html">备份/恢复</a>路径；协议变更注明 Dashboard/Agent 配对提交。发布、合并、部署是与本地验证不同的操作，不把“构建成功”写成“线上已生效”。</p>`,25)])])}const F=a(n,[["render",h]]);export{c as __pageData,F as default};
